    dict(id='v1', src=None, when='Oct 19 12:55', title='Passage v1', critic=12, note='Not kept as a film. The frame sheets the critic saw are below.'),
    dict(id='v2', src=H + 'lab/tfu/renders/tempus_fugit_passage_v2.mp4', title='Passage v2', critic=13, note='All of round 1\'s faults addressed.'),
    dict(id='v3', src=H + 'lab/tfu/renders/tempus_fugit_passage_v3.mp4', title='Passage v3', critic=14, note='Seven of the eight round-2 fixes resolved.'),
